import{_ as t,o,c as l,a5 as V}from"./chunks/framework.DJo0M80U.js";const n=JSON.parse('{"title":"Vue 的 MVVM 模式","description":"Vue.js 是一个渐进式 JavaScript 框架，它使用了 MVVM（Model View ViewModel）模式来组织代码。MVVM 模式是一种软件架构设计模式，主要用于实现用户界面与业务逻辑的分离。MVVM 模式包括三部分：Model（模型）、View（视图）和 Vi。","frontmatter":{"title":"Vue 的 MVVM 模式","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","原理与手写实现"],"description":"Vue.js 是一个渐进式 JavaScript 框架，它使用了 MVVM（Model View ViewModel）模式来组织代码。MVVM 模式是一种软件架构设计模式，主要用于实现用户界面与业务逻辑的分离。MVVM 模式包括三部分：Model（模型）、View（视图）和 Vi。","sidebarWeight":15,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/原理/Vue 的 MVVM 模式.md"},"headers":[],"relativePath":"posts/Vue系统教程/05-原理与手写实现/Vue 的 MVVM 模式.md","filePath":"posts/Vue系统教程/05-原理与手写实现/Vue 的 MVVM 模式.md"}'),i={name:"posts/Vue系统教程/05-原理与手写实现/Vue 的 MVVM 模式.md"};function d(s,e,a,u,M,r){return o(),l("div",null,[...e[0]||(e[0]=[V('<div><h1 id="vue-的-mvvm-模式" tabindex="-1">Vue 的 MVVM 模式 <a class="header-anchor" href="#vue-的-mvvm-模式" aria-label="Permalink to &quot;Vue 的 MVVM 模式&quot;">​</a></h1><blockquote><p>本节目标：理解“Vue 的 MVVM 模式”的核心思路，并能把它用于实际开发或面试表达。 Vue.js 是一个渐进式 JavaScript 框架，它使用了 MVVM（Model-View-ViewModel）模式来组织代码。MVVM 模式是一种软件架构设计模式，主要用于实现用户界面与业务逻辑的分离。MVVM 模式包括三部分：Model（模型）、View（视图）和 ViewModel（视图模型）。</p></blockquote><ol><li><p>Model（模型） Model 表示应用程序的基本数据结构和业务逻辑。它通常包含应用程序的状态和处理这些状态的业务逻辑。在 Vue.js 中，Model 通常是 Vue 实例中的 <code>data</code> 属性，它持有应用程序的数据。 const vm = new Vue({ data: { message: &#39;Hello, Vue.js!&#39; } });</p></li><li><p>View（视图） View 是用户界面，表示应用程序的表现层。它负责将数据展示给用户，并将用户的操作传递给 ViewModel。View 通常是 HTML 页面，在 Vue.js 中，模板（Template）部分表示视图。 &lt;div id=&quot;app&quot;&gt; {{ message }} &lt;/div&gt;</p></li><li><p>ViewModel（视图模型） ViewModel 是 View 和 Model 之间的桥梁，负责将 Model 的数据和 View 进行双向绑定。在 Vue.js 中，Vue 实例本身就充当了 ViewModel 的角色，它通过数据绑定（Data Binding）和 DOM 监听器（DOM Listeners）来实现视图和数据的同步。 const vm = new Vue({ el: &#39;#app&#39;, data: { message: &#39;Hello, Vue.js!&#39; } });</p></li></ol><p>MVVM 的工作原理</p><ol><li><strong>数据绑定</strong>：</li></ol><ul><li>Vue.js 使用双向数据绑定（Two-Way Data Binding），通过 <code>v-model</code> 指令实现表单控件与数据的双向绑定。</li><li>Vue.js 还使用单向数据绑定，通过 Mustache 语法 <code>{{}}</code> 将数据绑定到视图上。</li></ul><ol start="2"><li><strong>指令</strong>：</li></ol><ul><li>Vue.js 提供了多种指令，如 <code>v-if</code>、<code>v-for</code>、<code>v-bind</code> 等，用于操作 DOM 和绑定数据。</li></ul><ol start="3"><li><strong>事件监听</strong>：</li></ol><ul><li>Vue.js 提供了 <code>v-on</code> 指令，用于监听用户事件，并将事件处理函数绑定到 ViewModel 上。</li></ul><ol start="4"><li><strong>响应式系统</strong>：</li></ol><ul><li>Vue.js 的核心是响应式系统，它通过劫持对象属性的 <code>getter</code> 和 <code>setter</code>，实现数据变化时自动更新视图。</li><li>当 Model 中的数据发生变化时，Vue.js 的响应式系统会检测到变化，并通知 ViewModel 更新视图。</li></ul><p>示例代码 以下是一个完整的示例，展示了 Vue.js 的 MVVM 模式： &lt;!DOCTYPE html&gt; &lt;html lang=&quot;en&quot;&gt; &lt;head&gt; &lt;meta charset=&quot;UTF-8&quot;&gt; &lt;title&gt;Vue MVVM Example&lt;/title&gt; &lt;script src=&quot;<a href="https://cdn.jsdelivr.net/npm/vue@2" target="_blank" rel="noreferrer">https://cdn.jsdelivr.net/npm/vue@2</a>&quot;&gt;&lt;/script&gt; &lt;/head&gt; &lt;body&gt; &lt;div id=&quot;app&quot;&gt; &lt;p&gt;{{ message }}&lt;/p&gt; &lt;input v-model=&quot;message&quot; placeholder=&quot;Edit me&quot;&gt; &lt;/div&gt; &lt;script&gt; new Vue({ el: &#39;#app&#39;, data: { message: &#39;Hello, Vue.js!&#39; } }); &lt;/script&gt; &lt;/body&gt; &lt;/html&gt;</p><p>在这个示例中：</p><ul><li><strong>Model</strong> 是 Vue 实例中的 <code>message</code> 数据。</li><li><strong>View</strong> 是 HTML 模板中的 <code>\\&lt;div id=&quot;app&quot;\\&gt;</code> 部分。</li><li><strong>ViewModel</strong> 是 Vue 实例，它通过 <code>v-model</code> 指令实现了双向数据绑定，使得输入框中的内容可以实时同步到 <code>message</code> 数据中，并且 <code>message</code> 数据的变化会实时更新到页面。</li></ul><p>总结 Vue.js 的 MVVM 模式通过将数据（Model）、视图（View）和视图模型（ViewModel）分离，实现了代码的模块化和解耦。Vue.js 的双向数据绑定、指令系统和响应式机制使得开发者可以轻松地构建动态和响应式的用户界面。</p></div>',1)])])}const p=t(i,[["render",d]]);export{n as __pageData,p as default};
